declare_lint ! { #[doc = " The `dyn_drop` lint checks for trait objects with `std::ops::Drop`."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn foo(_x: Box<dyn Drop>) {}"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " A trait object bound of the form `dyn Drop` is most likely misleading"] #[doc = " and not what the programmer intended."] #[doc = ""] #[doc = " `Drop` bounds do not actually indicate whether a type can be trivially"] #[doc = " dropped or not, because a composite type containing `Drop` types does"] #[doc = " not necessarily implement `Drop` itself. Naïvely, one might be tempted"] #[doc = " to write a deferred drop system, to pull cleaning up memory out of a"] #[doc = " latency-sensitive code path, using `dyn Drop` trait objects. However,"] #[doc = " this breaks down e.g. when `T` is `String`, which does not implement"] #[doc = " `Drop`, but should probably be accepted."] #[doc = ""] #[doc = " To write a trait object bound that accepts anything, use a placeholder"] #[doc = " trait with a blanket implementation."] #[doc = ""] #[doc = " ```rust"] #[doc = " trait Placeholder {}"] #[doc = " impl<T> Placeholder for T {}"] #[doc = " fn foo(_x: Box<dyn Placeholder>) {}"] #[doc = " ```"] pub DYN_DROP , Warn , "trait objects of the form `dyn Drop` are useless" }